  ['Entry blend time'] = 'Tempo de transição ao entrar', ['Time to fade in when entering a new state (yielding, overtaking, etc.).\nHigher = smoother transitions.'] = 'Tempo para entrar gradualmente em um novo estado (ceder, ultrapassar etc.).\nValores maiores deixam a transição mais suave.', ['Exit blend time'] = 'Tempo de transição ao sair', ['Time to fade out when leaving a state.'] = 'Tempo para sair gradualmente de um estado.', ['AI reaction delay'] = 'Atraso de reação da IA', ['How long the AI waits before reacting to a situation.'] = 'Quanto tempo a IA espera antes de reagir a uma situação.', ['AI reaction jitter'] = 'Variação do tempo de reação da IA', ['Random extra delay added on top of reaction delay.'] = 'Atraso aleatório adicional somado ao tempo de reação.', ['AI lookahead window'] = 'Janela de antecipação da IA', ['How far ahead the AI looks to anticipate.'] = 'Quanto à frente a IA observa para antecipar situações.', ['Lookahead confidence threshold'] = 'Limite de confiança da antecipação', ['Min confidence to act on lookahead.'] = 'Confiança mínima para agir com base na antecipação.', ['Point-by speed delta (km/h)'] = 'Diferença de velocidade para sinalizar (km/h)', ['How much faster (km/h) a car behind must be to yield.'] = 'Quanto mais rápido (km/h) o carro de trás deve estar para pedir passagem.', ['Defense duration min (s)'] = 'Duração mínima da defesa (s)', ['Minimum time defending position before yielding.'] = 'Tempo mínimo defendendo a posição antes de ceder.', ['Defense duration max (s)'] = 'Duração máxima da defesa (s)', ['Maximum time defending position before yielding.'] = 'Tempo máximo defendendo a posição antes de ceder.', ['Overtake aggressiveness'] = 'Agressividade ao ultrapassar', ['How assertive AI is when space is marginal.'] = 'O quanto a IA se impõe quando o espaço é limitado.', ['Human errors enabled'] = 'Erros humanos ativados', ['Whether AI cars make realistic mistakes (lock-ups, traction loss).'] = 'Define se os carros da IA cometem erros realistas (travamento de rodas, perda de tração).', ['Lock-up probability (per sec)'] = 'Probabilidade de travamento (por s)', ['Chance per second of brake lock-up when braking hard.'] = 'Chance por segundo de travamento dos freios em frenagens fortes.', ['Traction mistake prob (per sec)'] = 'Probabilidade de erro de tração (por s)', ['Chance per second of traction loss on throttle.'] = 'Chance por segundo de perda de tração ao acelerar.', ['Error cooldown (s)'] = 'Intervalo mínimo entre erros (s)', ['Minimum time between human errors on the same car.'] = 'Tempo mínimo entre erros humanos do mesmo carro.',
  ['Handle Yielding'] = 'Ativar cessão de passagem', ['If enabled, AI cars will attempt to yield to the specified Yielding Lateral Offset side of the track'] = 'Se ativado, a IA tentará ceder passagem para o lado definido no deslocamento lateral de cessão.', ['Check sides while yielding'] = 'Verificar os lados ao ceder', ["If enabled, cars will check for other cars on the side when yielding so they don't crash into them."] = 'Se ativado, os carros verificam se há outros ao lado antes de ceder para evitar colisões.', ['Require overtaking car to be on overtaking lane to yield'] = 'Exigir que o carro ultrapassando esteja na faixa de ultrapassagem', ["If enabled, the yielding car will only yield if the overtaking car is actually driving on the overtaking lane."] = 'Se ativado, o carro só cede se o veículo que ultrapassa estiver de fato na faixa de ultrapassagem.',
